        if resources:
            best = None
            for (rx, ry) in resources:
                if not inb(rx, ry):
                    continue
                d = (rx - sx) * (rx - sx) + (ry - sy) * (ry - sy)
                if best is None or d < best[0]:
                    best = (d, rx, ry)
            if best:
                return best[1], best[2]
        corners = [(0, 0), (w - 1, 0), (w - 1, h - 1), (0, h - 1)]
        tx, ty = max(corners, key=lambda c: (c[0] - ox) * (c[0] - ox) + (c[1] - oy) * (c[1] - oy))
        return tx, ty

